int calculate(int x, int y) { return x + y; }

// 1. Raw Declaration
int (*func_ptr)(int, int);
func_ptr = &calculate;

// 2. Typedef Declaration (Preferred)
typedef int (*BinaryOp)(int, int);
BinaryOp op_handle = calculate; // Function name decays to pointer

// 3. Invocation Methods
int result_a = (*func_ptr)(10, 5); // Explicit dereference (C89)
int result_b = op_handle(2, 3);    // Implicit dereference (Modern C)

// 4. Using in Structs/Callbacks
struct Callback {
    BinaryOp func;
};
